"""NCI-NOVEL-01: research-only public-observation learners, no native owner writes.
Learners never import the source generator, laws, or evaluator metadata.
"""
from __future__ import annotations
import hashlib, json, math, time
from collections import defaultdict
import ast

MAX_GATES = 4
NOISE = 0.06


def grammar():
    """Enumerate unique Boolean signatures generated by <=4 {AND,OR,XOR} gates.
    NOT is an allowed free input/output complement. No source law is supplied.
    """
    basic = [0,255,240,204,170]
    costs = {}
    for b in basic:
        costs[b] = 0
        costs[b ^ 255] = 0
    levels = [sorted(costs)]
    for n in range(1, MAX_GATES + 1):
        new = set()
        for leftcost in range(n):
            rightcost = n - leftcost - 1
            for left in levels[leftcost]:
                for right in levels[rightcost]:
                    for mask in (left & right, left | right, left ^ right):
                        for m in (mask, mask ^ 255):
                            if m not in costs:
                                new.add(m)
        for m in new:
            costs[m] = n
        levels.append(sorted(new))
    return tuple(sorted(costs)), costs

MASKS, COMPLEXITY = grammar()


def value(mask:int, features:tuple[int,int,int]) -> int:
    a,b,c=features
    assert all(type(v) is int and v in (0,1) for v in features)
    return (mask >> (a*4+b*2+c))&1


def canonical(data):
    return json.dumps(data,sort_keys=True,separators=(',',':'),allow_nan=False).encode('ascii')


def digest(data):
    return hashlib.sha256(data).hexdigest()


def sigmoid_probability(bit):
    return (1-NOISE) if bit else NOISE


class BooleanPosterior:
    def __init__(self, strategy):
        assert strategy in ('MAP','BMA')
        self.strategy=strategy
        self.scores = [-0.58*COMPLEXITY[m] for m in MASKS]
        self.n=0
        self.ids=set()
        self.last_r=set()
        self.counts=[0,0]
        self.last_errors=[]

    def predict(self, x):
        if self.strategy=='MAP':
            best=max(range(len(MASKS)),key=lambda j:(self.scores[j],-COMPLEXITY[MASKS[j]],-MASKS[j]))
            return sigmoid_probability(value(MASKS[best],x))
        m=max(self.scores)
        nums=[math.exp(v-m) for v in self.scores]
        total=sum(nums)
        return sum(w*sigmoid_probability(value(mask,x)) for w,mask in zip(nums,MASKS))/total

    def observe(self,x,y,witness_id,r):
        assert witness_id[:32] not in self.ids
        assert type(y) is int and y in (0,1)
        before=self.predict(x)
        self.ids.add(witness_id[:32])
        self.last_r.add(r)
        self.last_errors.append((before-y)**2)
        if len(self.last_errors)>24:self.last_errors.pop(0)
        self.counts[y]+=1
        for i,mask in enumerate(MASKS):
            self.scores[i]+=math.log(1-NOISE) if value(mask,x)==y else math.log(NOISE)
        self.n+=1

    def confidence(self):
        m=max(self.scores)
        norm=sum(math.exp(v-m) for v in self.scores)
        confidence=1/norm
        best=max(range(len(MASKS)),key=lambda j:(self.scores[j],-COMPLEXITY[MASKS[j]],-MASKS[j]))
        return {'signature':f'{MASKS[best]:02x}', 'posterior_probability':confidence,
                'observed_r_support':sorted(self.last_r), 'witnesses':self.n,
                'recent_brier':sum(self.last_errors)/len(self.last_errors) if self.last_errors else None,
                'identified':confidence>=0.95 and len(self.last_r)==2 and self.n>=24 and (sum(self.last_errors)/len(self.last_errors))<=0.15}

    def state(self):
        return {'type':self.strategy,'scores':[round(s,12) for s in self.scores],
                'n':self.n,'ids':sorted(self.ids),'r_seen':sorted(self.last_r),
                'counts':self.counts,'errors':[round(v,12) for v in self.last_errors]}


class Tabular:
    def __init__(self, mode):
        assert mode in ('FULL','SUBSET','RECURRENT')
        self.mode=mode
        self.counts=defaultdict(lambda:[0,0]);self.ids=set();self.previous=0

    def _key(self,x,r):
        z=(*x,r)
        if self.mode=='FULL':return tuple(z)
        if self.mode=='RECURRENT':return (*z,self.previous)
        return tuple(z)

    def predict(self,x,r):
        if self.mode=='SUBSET':
            res=[]
            for subset in (15,7,11,13,14,3,5,9,6,10,12,1,2,4,8,0):
                key=(subset,tuple(v for i,v in enumerate((*x,r)) if (subset>>i)&1))
                zero,one=self.counts.get(key,(0,0))
                count=zero+one
                res.append(((one+0.5)/(count+1), (count+1)/(count+5)))
            return sum(a*b for a,b in res)/sum(b for a,b in res)
        zero,one=self.counts.get(self._key(x,r),(0,0))
        return (one+0.5)/(zero+one+1)

    def observe(self,x,y,witness_id,r):
        assert witness_id[:32] not in self.ids
        self.ids.add(witness_id[:32])
        if self.mode=='SUBSET':
            z=(*x,r)
            for subset in range(16):
                key=(subset,tuple(v for i,v in enumerate(z) if subset>>i&1))
                self.counts[key][y]+=1
        else:self.counts[self._key(x,r)][y]+=1
        self.previous=y

    def state(self):
        return {'type':self.mode,'counts':[[repr(k),*v] for k,v in sorted(self.counts.items())],
                'ids':sorted(self.ids),'previous':self.previous}


class NativeResearchArm:
    """Research fixture only. Source-declared namespaces isolate OLD and NEW.
    A distinct owner-trained checkpoint is NEVER imported or simulated here.
    """
    def __init__(self,kind):
        assert kind in ('MAP','BMA','FULL','SUBSET','RECURRENT')
        self.kind=kind
        self.models={}
        self.event_count=0
        self.event_digest='0'*64

    def component(self,source_ids,stage):
        key=(tuple(source_ids),stage)
        if key not in self.models:
            self.models[key]=BooleanPosterior(self.kind) if self.kind in ('MAP','BMA') else Tabular(self.kind)
        return self.models[key]

    def predict(self,source_ids,stage,features,r):
        m=self.component(source_ids,stage)
        return m.predict(features) if self.kind in ('MAP','BMA') else m.predict(features,r)

    def update(self,source_ids,stage,features,r,outcome,identifier):
        m=self.component(source_ids,stage)
        m.observe(features,outcome,identifier,r)
        self.event_count+=1
        self.event_digest=digest((self.event_digest+identifier).encode('ascii'))

    def checkpoint(self):
        payload={'schema':'nci-novel01.source-free-learner.v1','kind':self.kind,
                'event_count':self.event_count,'event_digest':self.event_digest,'models':{str(k):v.state() for k,v in sorted(self.models.items())},
                'native_accepted':False,'source_authentication':'SYNTHETIC_FIXTURE_ONLY'}
        raw=canonical(payload)
        return {'sha256':digest(raw),'bytes':len(raw),'raw':raw}


    @classmethod
    def restore(cls,raw,expected_sha256):
        if digest(raw)!=expected_sha256:raise ValueError('CHECKPOINT_PIN')
        data=json.loads(raw)
        if set(data)!={'schema','kind','event_count','event_digest','models',
                           'native_accepted','source_authentication'} or data['schema']!='nci-novel01.source-free-learner.v1' or data['native_accepted'] is not False or data['source_authentication']!='SYNTHETIC_FIXTURE_ONLY':
            raise ValueError('CHECKPOINT_CONTRACT')
        restored=cls(data['kind'])
        restored.event_count=data['event_count']
        restored.event_digest=data['event_digest']
        for key,state in data['models'].items():
            parsed=ast.literal_eval(key)
            if not isinstance(parsed,tuple) or len(parsed)!=2 or parsed[1] not in ('t','y'):
                raise ValueError('CHECKPOINT_KEY')
            model=restored.component(parsed[0],parsed[1])
            if state['type']!=data['kind']:
                raise ValueError('CHECKPOINT_MODEL')
            model.ids=set(state['ids'])
            if isinstance(model,BooleanPosterior):
                if len(state['scores'])!=len(MASKS):raise ValueError('CHECKPOINT_GRAMMAR')
                model.scores=state['scores']
                model.n=state['n']
                model.last_r=set(state['r_seen'])
                model.counts=state['counts']
                model.last_errors=state['errors']
            else:
                model.previous=state['previous']
                for literal,zero,one in state['counts']:
                    model.counts[ast.literal_eval(literal)]=[zero,one]
        if restored.checkpoint()['raw']!=raw:raise ValueError('CHECKPOINT_COLD_DRIFT')
        return restored

    def old_digest(self,old_ids):
        payload={k:v.state() for k,v in self.models.items() if k[0]==tuple(old_ids)}
        return digest(canonical({str(k):v for k,v in sorted(payload.items())}))
